fn eth_attest_init_instance_impl(args: &str) -> Result<String, String> {
    let v: Value = serde_json::from_str(args).map_err(|e| format!("invalid JSON: {}", e))?;
    let program_id = parse_program_id_hex(v["program_id_hex"].as_str().ok_or("missing program_id_hex")?)?;
    let wallet = init_wallet(&v)?;

    let instance_id = parse_bytes32(v["instance_id"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let store_seed = parse_bytes32(v["store_seed"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let records_seed = parse_bytes32(v["records_seed"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let config = v["config"].as_array().ok_or("expected array")?.iter().map(|item| Ok(item.as_u64().ok_or("expected number")? as u8)).collect::<Result<Vec<_>, String>>()?;
    let slot = { let _v = &v["slot"]; if let Some(_s) = _v.as_str() { _s.parse::<u64>().map_err(|_| format!("invalid u64: {}", _s))? } else { _v.as_u64().ok_or("expected u64")? } };
    let proposer_index = { let _v = &v["proposer_index"]; if let Some(_s) = _v.as_str() { _s.parse::<u64>().map_err(|_| format!("invalid u64: {}", _s))? } else { _v.as_u64().ok_or("expected u64")? } };
    let parent_root = parse_bytes32(v["parent_root"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let state_root = parse_bytes32(v["state_root"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let body_root = parse_bytes32(v["body_root"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let keys_root = parse_bytes32(v["keys_root"].as_str().ok_or("expected string for [u8; 32]")?)?;
    let aggregate = v["aggregate"].as_array().ok_or("expected array")?.iter().map(|item| Ok(item.as_u64().ok_or("expected number")? as u8)).collect::<Result<Vec<_>, String>>()?;
    let branch = v["branch"].as_array().ok_or("expected array")?.iter().map(|item| Ok(parse_bytes32(item.as_str().ok_or("expected string for [u8; 32]")?)?)).collect::<Result<Vec<_>, String>>()?;

    let clock = parse_account_id(v["clock"].as_str().ok_or("missing clock")?)?;
    let instance = compute_pda_with_program(&program_id, &[
        instance_id.as_ref(),
    ])?;
    let store = compute_pda_with_program(&program_id, &[
        store_seed.as_ref(),
    ])?;
    let records = compute_pda_with_program(&program_id, &[
        records_seed.as_ref(),
    ])?;

    let account_ids: Vec<AccountId> = vec![
        instance,
        store,
        records,
        clock,
    ];
    let signer_ids: Vec<AccountId> = vec![
    ];

    let instruction = EthAttestInstruction::InitInstance {
        instance_id,
        store_seed,
        records_seed,
        config,
        slot,
        proposer_index,
        parent_root,
        state_root,
        body_root,
        keys_root,
        aggregate,
        branch,
    };

    let rt = get_runtime();
    let tx_hash = rt.block_on(async {
        let nonces = wallet.get_accounts_nonces(signer_ids.clone()).await
            .map_err(|e| format!("nonces: {}", e))?;
        let mut signing_keys = Vec::new();
        for sid in &signer_ids {
            let key = wallet.storage().user_data
                .get_pub_account_signing_key(*sid)
                .ok_or_else(|| format!("signing key not found for {}", sid))?;
            signing_keys.push(key);
        }
        let message = Message::try_new(program_id, account_ids, nonces, instruction)
            .map_err(|e| format!("message: {:?}", e))?;
        let witness_set = WitnessSet::for_message(&message, &signing_keys);
        let tx = PublicTransaction::new(message, witness_set);
        let raw = wallet.sequencer_client.send_transaction(common::transaction::NSSATransaction::Public(tx)).await
            .map_err(|e| format!("submit: {}", e))?;
        let tx_hash_hex = hex::encode(raw.0);
        let poller = wallet::poller::TxPoller::new(wallet.config(), wallet.sequencer_client.clone());
        poller.poll_tx(raw).await.map_err(|e| format!("confirm: {}", e))?;
        Ok::<String, String>(tx_hash_hex)
    })?;

    Ok(json!({"success": true, "tx_hash": tx_hash}).to_string())
}

