pub extern "C" fn eth_attest_free_string(s: *mut c_char) {
    if !s.is_null() { unsafe { drop(CString::from_raw(s)) }; }
}

#[no_mangle]
pub extern "C" fn eth_attest_version() -> *mut c_char {
    to_cstring("0.1.0".to_string())
}

#[no_mangle]
pub extern "C" fn eth_attest_program_id() -> *mut c_char {
    let rel = "methods/guest/target/riscv32im-risc0-zkvm-elf/docker/eth_attest.bin";
    let data = std::env::current_dir().ok().and_then(|cwd| {
        cwd.ancestors().take(6).find_map(|dir| std::fs::read(dir.join(rel)).ok())
    });
    let data = match data { Some(d) => d, None => return std::ptr::null_mut() };
    let program = match Program::new(data) { Ok(p) => p, Err(_) => return std::ptr::null_mut() };
    let id = program.id();
    let hex: String = id.iter().flat_map(|w| w.to_le_bytes()).map(|b| format!("{:02x}", b)).collect();
    let json = json!({"program_id_hex": hex}).to_string();
    CString::new(json).map(|cs| cs.into_raw()).unwrap_or(std::ptr::null_mut())
}

